from prometheus_client import CONTENT_TYPE_LATEST, Counter, Gauge, Histogram, generate_latest

SOC_EVENTS_PROCESSED_TOTAL = Counter(
    "soc_events_processed_total",
    "Total events processed by the SOC monitor.",
    labelnames=("source", "event_type"),
)

SOC_ALERTS_GENERATED_TOTAL = Counter(
    "soc_alerts_generated_total",
    "Total alerts generated by the SOC monitor.",
    labelnames=("threat_type", "severity"),
)

SOC_DETECTION_RULE_MATCHES_TOTAL = Counter(
    "soc_detection_rule_matches_total",
    "Total rule matches for detected threats.",
    labelnames=("rule_name", "threat_type"),
)

SOC_COLLECTOR_UP = Gauge(
    "soc_collector_up",
    "Collector health as a boolean gauge (1=up, 0=down).",
    labelnames=("collector",),
)

SOC_COLLECTOR_ERRORS_TOTAL = Counter(
    "soc_collector_errors_total",
    "Total collector processing failures.",
    labelnames=("collector",),
)

SOC_DATABASE_ERRORS_TOTAL = Counter(
    "soc_database_errors_total",
    "Total database operation failures.",
)

SOC_EVENT_PROCESSING_DURATION_SECONDS = Histogram(
    "soc_event_processing_duration_seconds",
    "Duration spent processing a single event.",
    labelnames=("source",),
)

SOC_HTTP_REQUESTS_TOTAL = Counter(
    "soc_http_requests_total",
    "Total HTTP requests received by the API.",
    labelnames=("method", "route", "status_code"),
)

SOC_HTTP_REQUEST_DURATION_SECONDS = Histogram(
    "soc_http_request_duration_seconds",
    "HTTP request processing time in seconds.",
    labelnames=("method", "route"),
)
